export function getModuleTree() {
  const tree: Record<string, Record<string, typeof erpTables>> = {};
  for (const t of erpTables) {
    if (!tree[t.module]) tree[t.module] = {};
    if (!tree[t.module][t.sub]) tree[t.module][t.sub] = [];
    tree[t.module][t.sub].push(t);
  }
  return tree;
}